-- Backend Engineering ("The Fracture") Act 17 -- "Jobs & Message Queues" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 (20260810040000_backend_act1_content.sql)
-- and Act 15 (20260810190000_backend_act15_content.sql).
-- References world-be-17, whose narrative metadata was pre-authored in
-- 20260810200000_backend_acts16_20_and_arc4.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be17', 'world-be-17', 'jobs-and-message-queues', '17A - Jobs & Message Queues', 'A single API call tried to message a million residents inline, timed out mid-batch, and left Forge with no idea who actually got the alert.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be17-1', 'campaign-be17', 'off-the-request-path', 'Off the Request Path', 'Moving slow work out of the request/response cycle, and the queue that makes that possible.', 1),
  ('operation-be17-2', 'campaign-be17', 'failure-with-a-plan', 'Failure With a Plan', 'Retries, backoff, and the safeguards that decide whether failure is survivable or catastrophic.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be17-01', 'world-be-17', 'campaign-be17', 'operation-be17-1', 'request-vs-background-work', 'Request vs Background Work', 'A city-wide outage advisory went out as one synchronous API call trying to message a million residents inline. It timed out with the batch half-sent. The fix starts with a question nobody asked first: does this even belong in the request at all?', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"request-vs-background-sim"}'::jsonb, '{"xp":212,"credits":40}'::jsonb, false, 1),
  ('mission-be17-02', 'world-be-17', 'campaign-be17', 'operation-be17-1', 'job-queues', 'Job Queues', 'Taking work off the request path means putting it somewhere durable enough to survive a crash between "accepted" and "done." That somewhere has a name.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be17-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"job-queue-basics-sim"}'::jsonb, '{"xp":214,"credits":40}'::jsonb, false, 2),
  ('mission-be17-03', 'world-be-17', 'campaign-be17', 'operation-be17-1', 'producers-and-consumers', 'Producers and Consumers', 'A queue is just a list until something adds to it and something else takes from it. Two roles, cleanly separated, and half of every queueing bug traces back to blurring them.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be17-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"producer-consumer-sim"}'::jsonb, '{"xp":215,"credits":40}'::jsonb, false, 3),
  ('mission-be17-04', 'world-be-17', 'campaign-be17', 'operation-be17-1', 'bullmq-fundamentals', 'BullMQ Fundamentals', 'Forge Division does not hand-roll a queue from scratch. BullMQ, backed by Redis, is the tool that turns "producer and consumer" from a concept into working code.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be17-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"bullmq-fundamentals-sim"}'::jsonb, '{"xp":216,"credits":40}'::jsonb, false, 4),
  ('mission-be17-05', 'world-be-17', 'campaign-be17', 'operation-be17-1', 'delayed-and-scheduled-jobs', 'Delayed and Scheduled Jobs', 'Not every job should run the instant it is added. Some need to wait an hour. Some need to run every night at 2 AM, forever. A queue that can only run things immediately cannot do either.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be17-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"delayed-jobs-sim"}'::jsonb, '{"xp":217,"credits":41}'::jsonb, false, 5),
  ('mission-be17-06', 'world-be-17', 'campaign-be17', 'operation-be17-1', 'priorities', 'Priorities', 'A city-wide emergency alert and a weekly newsletter digest should never wait in the same line the same way. Priority is what lets a queue tell them apart.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be17-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"job-priority-sim"}'::jsonb, '{"xp":218,"credits":41}'::jsonb, false, 6),
  ('mission-be17-07', 'world-be-17', 'campaign-be17', 'operation-be17-2', 'retries', 'Retries', 'The outage-advisory job failed partway through and the naive fix -- just run it again -- is exactly the decision that turned one bad batch into forty duplicate alerts for some residents and zero for others.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be17-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"retry-basics-sim"}'::jsonb, '{"xp":220,"credits":42}'::jsonb, false, 7),
  ('mission-be17-08', 'world-be-17', 'campaign-be17', 'operation-be17-2', 'exponential-backoff', 'Exponential Backoff', 'Retrying immediately, over and over, against a system that is already struggling is how a brief failure becomes a sustained one. Backoff is the discipline of waiting longer each time.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be17-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"exponential-backoff-sim"}'::jsonb, '{"xp":222,"credits":42}'::jsonb, false, 8),
  ('mission-be17-09', 'world-be-17', 'campaign-be17', 'operation-be17-2', 'jitter', 'Jitter', 'Exponential backoff alone has a hidden flaw: a thousand jobs that all failed at the same instant will all retry at the same instant too, every time, in perfect lockstep. Jitter is the fix nobody notices until it is missing.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be17-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"retry-jitter-sim"}'::jsonb, '{"xp":224,"credits":43}'::jsonb, false, 9),
  ('mission-be17-10', 'world-be-17', 'campaign-be17', 'operation-be17-2', 'dead-letter-jobs', 'Dead-Letter Jobs', 'A job cannot retry forever. At some point it has to stop, and land somewhere a human can actually find it -- not vanish. That somewhere is the path the outage advisory never had.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be17-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"dead-letter-queue-sim"}'::jsonb, '{"xp":226,"credits":43}'::jsonb, false, 10),
  ('mission-be17-11', 'world-be-17', 'campaign-be17', 'operation-be17-2', 'idempotent-workers', 'Idempotent Workers', 'Retries only become safe once running a job twice is guaranteed to look exactly like running it once. That guarantee has a name, and the outage-advisory worker never had it.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be17-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"idempotent-worker-sim"}'::jsonb, '{"xp":228,"credits":44}'::jsonb, false, 11),
  ('mission-be17-12', 'world-be-17', 'campaign-be17', 'operation-be17-2', 'the-million-jobs', 'The Million Jobs', 'The full incident, laid out at last: some residents got the outage advisory zero times, others got it forty, and the dead-letter path meant to catch exactly this kind of failure was never wired up at all.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be17-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"million-jobs-boss-sim"}'::jsonb, '{"xp":510,"credits":118,"badgeIds":["million-jobs"],"skillXp":{"messaging":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be17-01', 1, 'mira', 'Caching solved the read-load problem. It also exposed the next one: expensive work -- sending notifications, generating reports -- has been happening inside the request path this whole time, and it should never have been there.'),
  ('mission-be17-01', 2, 'forge', 'Here is the incident that made it undeniable. A city-wide outage advisory went out as a single API call. That call tried to message one million residents, synchronously, inline, one at a time, before it would let itself return.'),
  ('mission-be17-01', 3, 'forge', 'It timed out. Half the batch never got sent at all. And the request that triggered it had no way to tell you that -- it just hung, then failed, with no record of where it stopped.'),
  ('mission-be17-01', 4, 'mira', 'Before we talk about queues, retries, any of it -- answer the more basic question. What actually belongs inside a request/response cycle, and what never should have been there in the first place?'),
  ('mission-be17-02', 1, 'forge', 'Taking work off the request path is easy to say. The hard part is: where does that work go while it waits to run? It has to survive the request finishing, the server restarting, even a crash mid-job.'),
  ('mission-be17-02', 2, 'forge', 'That durable, ordered, survives-a-crash place is a job queue. Not a to-do list in memory -- a real store, outside the request process, that remembers what still needs doing even if everything else falls over.'),
  ('mission-be17-03', 1, 'mira', 'A queue by itself does nothing. Something has to put work into it, and something else has to take work out. Producer and consumer. Keep those roles separate and the whole system stays easy to reason about.'),
  ('mission-be17-03', 2, 'mira', 'The outage-advisory endpoint should have been a producer: accept the request, drop one job onto a queue, return immediately. Instead it tried to be its own consumer too, synchronously, for a million residents, in the same breath as the request.'),
  ('mission-be17-04', 1, 'forge', 'Forge Division is not writing a queue from scratch. BullMQ, running on top of Redis, gives us producers, consumers, and a durable queue as a working library instead of a research project.'),
  ('mission-be17-04', 2, 'forge', 'Learn its actual building blocks -- Queue, Worker, Job -- before you touch a single line of the outage-advisory code. Guessing at BullMQ''s API is how the next incident gets written.'),
  ('mission-be17-05', 1, 'mira', 'Not every job wants to run the instant it is added. Some need to wait -- send this reminder in an hour. Some need to run on a schedule -- every night at 2 AM, no human involved. A queue that only knows "run it now" cannot do either.'),
  ('mission-be17-05', 2, 'mira', 'The city needed exactly this for the outage advisory: an initial wave now, and a scheduled follow-up nudge for anyone who never confirmed receipt.'),
  ('mission-be17-06', 1, 'forge', 'Not every job is equally urgent, either. A city-wide emergency alert and a weekly newsletter digest landing in the same queue at the same moment should not wait in the same line, in the order they happened to arrive.'),
  ('mission-be17-06', 2, 'forge', 'Priority lets a worker reach past the newsletter and grab the emergency alert first, every time, without the newsletter job ever needing to be rewritten to know it is less important.'),
  ('mission-be17-07', 1, 'mira', 'Now the part that actually broke the incident. The outage-advisory job failed partway through -- and the fix at the time was the simplest possible one: just run it again.'),
  ('mission-be17-07', 2, 'forge', 'That is exactly how one bad batch became forty duplicate alerts for some residents and zero for others. A retry without a plan is not a safeguard. It is the bug, wearing a safeguard''s name.'),
  ('mission-be17-08', 1, 'mira', 'Retrying is not the mistake. Retrying instantly, at full speed, against a system that just failed -- possibly because it was already overloaded -- is the mistake. That is exactly the moment retries need to slow down, not speed up.'),
  ('mission-be17-08', 2, 'forge', 'Exponential backoff: wait a little after the first failure, wait longer after the second, longer still after the third. Give the struggling system room to recover instead of burying it faster.'),
  ('mission-be17-09', 1, 'forge', 'Backoff alone has a quiet flaw. A thousand jobs that all failed in the same second will all compute the exact same delay and all retry in the exact same second again. Perfect lockstep, forever, against whatever is already struggling.'),
  ('mission-be17-09', 2, 'mira', 'Jitter breaks the lockstep: add a small random offset to each computed delay so a thousand simultaneous failures turn into a thousand retries spread across a window, not a second stampede timed to the millisecond.'),
  ('mission-be17-10', 1, 'mira', 'A job cannot retry forever, either. At some point -- after enough attempts -- it has to stop, and it has to land somewhere a human can actually see it and act on it. Not vanish. Not silently drop.'),
  ('mission-be17-10', 2, 'forge', 'That somewhere is a dead-letter queue. The outage-advisory system was supposed to have one. It did not. Every job that exhausted its retries simply disappeared -- no record, no alert, no way to know who never got their message.'),
  ('mission-be17-11', 1, 'mira', 'One more piece, and it is the one retries actually depend on. Running the same job twice has to produce the same result as running it once -- not "send the alert again," but "confirm the alert was already sent and stop."'),
  ('mission-be17-11', 2, 'forge', 'That property is idempotency, and the outage-advisory worker never had it. Every retry re-sent the message from scratch, with nothing recording who had already received it. That is the other half of why some residents got forty copies.'),
  ('mission-be17-12', 1, 'mira', 'Here is the whole incident, laid out end to end. One API call, a million residents, sent synchronously and inline. It timed out with the batch half-sent.'),
  ('mission-be17-12', 2, 'forge', 'The retry logic behind it had no backoff and no idempotency key. Every timeout triggered a full resubmission from the start. Some residents got the alert zero times. Others got it forty.'),
  ('mission-be17-12', 3, 'mira', 'And the dead-letter path that should have caught every one of those failed sends -- the safety net for exactly this kind of mess -- was never wired up at all. I have three explanations for what actually went wrong. Only one of them, taken together, actually accounts for the whole incident.'),
  ('mission-be17-12', 4, 'forge', '...one more thing, while you work. I finally tracked down the dead-letter queue that was supposed to exist. It does, technically -- nothing was ever consuming from it. Its name in the broker config is prefixed with "//". Same mark. Still not today''s bug.'),
  ('mission-be17-12', 5, 'mira', 'Filed, same as always. A job queue is enough for one service talking to itself. City-wide messaging has to fan reliably out to inventory, billing, notifications and audit -- systems that do not share a codebase, a language, or a deploy schedule.'),
  ('mission-be17-12', 6, 'forge', 'That needs a real message broker, not just a queue. RabbitMQ is next. For today: find every safeguard this system was missing.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be17-01-o1', 'mission-be17-01', 1, 'Judge the request path', 'Decide what kind of work should never run synchronously inside a request/response cycle.'),
  ('mission-be17-01-o2', 'mission-be17-01', 2, 'Diagnose the timeout', 'Find the evidence that explains why the outage-advisory request timed out with the batch half-sent.'),
  ('mission-be17-02-o1', 'mission-be17-02', 1, 'Name what a job queue actually guarantees', 'Decide what a durable job queue promises that an in-memory list of pending work does not.'),
  ('mission-be17-02-o2', 'mission-be17-02', 2, 'Match the job queue concept', 'Match each job-queue building block to what it actually does.'),
  ('mission-be17-03-o1', 'mission-be17-03', 1, 'Tell producer from consumer', 'Sort each responsibility into producer or consumer.'),
  ('mission-be17-03-o2', 'mission-be17-03', 2, 'Spot the blurred role', 'Find the evidence that shows the outage-advisory endpoint was acting as its own consumer.'),
  ('mission-be17-04-o1', 'mission-be17-04', 1, 'Match the BullMQ building block', 'Match each BullMQ concept to what it actually does.'),
  ('mission-be17-04-o2', 'mission-be17-04', 2, 'Find the wiring bug', 'Find the line that means jobs are added but nothing ever processes them.'),
  ('mission-be17-05-o1', 'mission-be17-05', 1, 'Tell delayed from scheduled', 'Match each requirement to the job type that actually fits it.'),
  ('mission-be17-05-o2', 'mission-be17-05', 2, 'Find the scheduling bug', 'Find the line that would make a "nightly at 2 AM" job run far more often than intended.'),
  ('mission-be17-06-o1', 'mission-be17-06', 1, 'Order by priority', 'Put four queued jobs in the order a priority-aware worker would actually process them.'),
  ('mission-be17-06-o2', 'mission-be17-06', 2, 'Judge the starvation risk', 'Decide what a naive priority implementation risks doing to low-priority jobs.'),
  ('mission-be17-07-o1', 'mission-be17-07', 1, 'Diagnose the duplicate alerts', 'Find the evidence that explains how one retry produced forty copies of the same alert.'),
  ('mission-be17-07-o2', 'mission-be17-07', 2, 'Judge the retry policy', 'Decide which failures are actually worth retrying at all.'),
  ('mission-be17-08-o1', 'mission-be17-08', 1, 'Order the backoff sequence', 'Put a well-behaved exponential-backoff retry sequence in order.'),
  ('mission-be17-08-o2', 'mission-be17-08', 2, 'Find the backoff bug', 'Find the line that means every retry waits the exact same fixed delay instead of backing off.'),
  ('mission-be17-09-o1', 'mission-be17-09', 1, 'Name what jitter actually fixes', 'Decide what problem jitter solves that plain exponential backoff does not.'),
  ('mission-be17-09-o2', 'mission-be17-09', 2, 'Find the missing jitter', 'Find the line in this retry-delay function that computes a delay with no randomness in it at all.'),
  ('mission-be17-10-o1', 'mission-be17-10', 1, 'Order the dead-letter path', 'Put the lifecycle of a job that exhausts its retries in order.'),
  ('mission-be17-10-o2', 'mission-be17-10', 2, 'Diagnose the missing safety net', 'Find the evidence that explains why failed jobs vanished with no record at all.'),
  ('mission-be17-11-o1', 'mission-be17-11', 1, 'Name what idempotency actually guarantees', 'Decide what an idempotent worker promises about running the same job twice.'),
  ('mission-be17-11-o2', 'mission-be17-11', 2, 'Find the missing idempotency key', 'Find the line in this worker that would send a duplicate alert on every retry instead of detecting one already sent.'),
  ('mission-be17-12-o1', 'mission-be17-12', 1, 'Explanation Alpha', 'Judge whether this explanation actually accounts for the full incident.'),
  ('mission-be17-12-o2', 'mission-be17-12', 2, 'Explanation Bravo', 'Judge whether this explanation actually accounts for the full incident.'),
  ('mission-be17-12-o3', 'mission-be17-12', 3, 'Explanation Charlie', 'Judge whether this explanation actually accounts for the full incident.'),
  ('mission-be17-12-o4', 'mission-be17-12', 4, 'Fix the system', 'State the full set of safeguards that would have prevented this incident.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be17-01-o1-c1', 'mission-be17-01-o1', 1, 'multiple_choice', 'Which of these actually belongs inside the synchronous request/response cycle, running before the response is sent?', '{"question":"Which of these actually belongs inside the synchronous request/response cycle, running before the response is sent?","options":[{"id":"a","text":"Validating the incoming request and confirming it is authorized"},{"id":"b","text":"Sending the outage advisory to one million individual residents"},{"id":"c","text":"Generating a PDF report attached to the advisory"},{"id":"d","text":"Re-indexing a search index used by an unrelated feature"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be17-01-o2-c1', 'mission-be17-01-o2', 1, 'investigation', 'Which piece of evidence is the actual reason the request timed out with the batch half-sent?', '{"evidence":[{"id":"ev1","label":"Request handler code","detail":"The handler loops over all one million residents and calls sendAlert() for each one, awaiting each call, before returning a response"},{"id":"ev2","label":"Load balancer config","detail":"The load balancer enforces a 30-second timeout on all upstream requests"},{"id":"ev3","label":"Notification service metrics","detail":"Each individual sendAlert() call takes roughly 40-120ms to complete"}],"question":"Which piece of evidence is the actual reason the request timed out with the batch half-sent?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be17-02-o1-c1', 'mission-be17-02-o1', 1, 'multiple_choice', 'What does a real job queue guarantee that an in-memory array of "things to do later" does not?', '{"question":"What does a real job queue guarantee that an in-memory array of \"things to do later\" does not?","options":[{"id":"a","text":"Jobs run faster than they would synchronously"},{"id":"b","text":"The pending work survives a process restart or crash, because it lives outside the request process in durable storage"},{"id":"c","text":"Jobs never fail"},{"id":"d","text":"No code is needed to process the jobs"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be17-02-o2-c1', 'mission-be17-02-o2', 1, 'drag_and_drop', 'Match each job-queue building block to what it actually does.', '{"items":[{"id":"i1","text":"Job"},{"id":"i2","text":"Queue"},{"id":"i3","text":"Worker"},{"id":"i4","text":"Job state (waiting/active/completed/failed)"}],"targets":[{"id":"t1","label":"A single unit of work, with its data, waiting to be processed"},{"id":"t2","label":"The durable, ordered store holding jobs until something takes them"},{"id":"t3","label":"The process that pulls jobs off the queue and actually executes them"},{"id":"t4","label":"The tracked lifecycle of a job, so nothing is silently lost or double-counted"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-be17-03-o1-c1', 'mission-be17-03-o1', 1, 'drag_and_drop', 'Sort each responsibility into producer or consumer.', '{"items":[{"id":"d1","text":"Accepts the incoming API request and adds a job to the queue"},{"id":"d2","text":"Pulls the next available job off the queue"},{"id":"d3","text":"Actually sends the alert to a resident"},{"id":"d4","text":"Returns a response to the client immediately after enqueueing"},{"id":"d5","text":"Marks a job completed or failed once it finishes"}],"targets":[{"id":"producer","label":"Producer"},{"id":"consumer","label":"Consumer"}]}'::jsonb, '{"correctMapping":{"d1":"producer","d2":"consumer","d3":"consumer","d4":"producer","d5":"consumer"}}'::jsonb),
  ('mission-be17-03-o2-c1', 'mission-be17-03-o2', 1, 'investigation', 'Which piece of evidence shows the outage-advisory endpoint was blurring producer and consumer into one role?', '{"evidence":[{"id":"ev1","label":"Endpoint code","detail":"The API handler itself iterates the resident list and sends every alert, inline, before responding -- no queue is involved at all"},{"id":"ev2","label":"Deploy history","detail":"The endpoint has not been redeployed in three weeks"},{"id":"ev3","label":"Traffic pattern","detail":"The endpoint is called once, by an internal admin tool, not by residents"}],"question":"Which piece of evidence shows the outage-advisory endpoint was blurring producer and consumer into one role?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be17-04-o1-c1', 'mission-be17-04-o1', 1, 'drag_and_drop', 'Match each BullMQ concept to what it actually does.', '{"items":[{"id":"i1","text":"Queue"},{"id":"i2","text":"Worker"},{"id":"i3","text":"queue.add()"},{"id":"i4","text":"Redis"}],"targets":[{"id":"t1","label":"The BullMQ object representing a named queue, used by producers to enqueue jobs"},{"id":"t2","label":"The BullMQ object that consumes jobs from a queue and runs a processor function against each one"},{"id":"t3","label":"The producer-side call that actually creates and enqueues a new job"},{"id":"t4","label":"The durable store BullMQ actually persists queue and job state in"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-be17-04-o2-c1', 'mission-be17-04-o2', 1, 'code_debugging', 'Jobs are being added successfully, but nothing ever processes them. Which line is missing entirely from this file, judging by what is actually here?', '{"language":"typescript","code":"import { Queue } from \"bullmq\";\n\nconst alertQueue = new Queue(\"outage-alerts\", { connection });\n\nexport async function enqueueOutageAlert(residentId: string, message: string) {\n  await alertQueue.add(\"send-alert\", { residentId, message });\n}","question":"Jobs are being added to alertQueue successfully, but nothing ever sends the actual alerts. What is missing from this file entirely?"}'::jsonb, '{"requiredLineIds":["const alertQueue = new Queue(\"outage-alerts\", { connection });"]}'::jsonb),

  ('mission-be17-05-o1-c1', 'mission-be17-05-o1', 1, 'drag_and_drop', 'Match each requirement to the job type that actually fits it.', '{"items":[{"id":"i1","text":"Send this specific resident a follow-up reminder in exactly one hour"},{"id":"i2","text":"Run a database cleanup job every night at 2 AM, indefinitely"},{"id":"i3","text":"Process this alert as soon as a worker is free"}],"targets":[{"id":"t1","label":"Delayed job (one-time, runs after a delay)"},{"id":"t2","label":"Repeatable/scheduled job (recurring, on a cron-like schedule)"},{"id":"t3","label":"Immediate job (no delay or schedule)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),
  ('mission-be17-05-o2-c1', 'mission-be17-05-o2', 1, 'code_debugging', 'This job is meant to run once a night, at 2 AM. Which line means it will actually run every 2 minutes instead?', '{"language":"typescript","code":"await cleanupQueue.add(\n  \"nightly-cleanup\",\n  { scope: \"expired-alerts\" },\n  {\n    repeat: {\n      pattern: \"*/2 * * * *\"\n    }\n  }\n);","question":"This job is meant to run once a night, at 2 AM. Which line means it will actually run every 2 minutes instead?"}'::jsonb, '{"requiredLineIds":["      pattern: \"*/2 * * * *\""]}'::jsonb),

  ('mission-be17-06-o1-c1', 'mission-be17-06-o1', 1, 'interactive_diagram', 'Put these four queued jobs in the order a priority-aware worker would actually process them: emergency-alert (priority 1), password-reset-email (priority 2), weekly-digest (priority 5), analytics-rollup (priority 10).', '{"diagramId":"priority-processing-order","hotspots":[{"id":"emergency_alert","label":"emergency-alert (priority 1)","explanation":"Lowest priority number, processed first -- in most priority-queue implementations, lower numbers mean higher urgency."},{"id":"password_reset","label":"password-reset-email (priority 2)","explanation":"Time-sensitive for the user waiting on it, processed second."},{"id":"weekly_digest","label":"weekly-digest (priority 5)","explanation":"Not urgent, processed after anything more time-sensitive."},{"id":"analytics_rollup","label":"analytics-rollup (priority 10)","explanation":"Lowest urgency, processed last whenever a worker is finally free."}],"task":"Put these four queued jobs in the order a priority-aware worker would actually process them."}'::jsonb, '{"correctOrderIds":["emergency_alert","password_reset","weekly_digest","analytics_rollup"]}'::jsonb),
  ('mission-be17-06-o2-c1', 'mission-be17-06-o2', 1, 'multiple_choice', 'A queue only ever processes strictly by priority, with no other adjustment. What does that naive approach risk doing to low-priority jobs under sustained high-priority load?', '{"question":"A queue only ever processes strictly by priority, with no other adjustment. What does that naive approach risk doing to low-priority jobs under sustained high-priority load?","options":[{"id":"a","text":"Nothing -- priority never causes any downside"},{"id":"b","text":"Starvation -- if high-priority jobs keep arriving continuously, low-priority jobs can wait indefinitely and never get processed at all"},{"id":"c","text":"It causes the low-priority jobs to run faster"},{"id":"d","text":"It corrupts the low-priority job data"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be17-07-o1-c1', 'mission-be17-07-o1', 1, 'investigation', 'Which piece of evidence best explains how one retry produced forty duplicate copies of the same alert for some residents?', '{"evidence":[{"id":"ev1","label":"Retry code","detail":"On any failure, including a timeout, the entire batch job is resubmitted from the very first resident again, with no record of who had already been messaged"},{"id":"ev2","label":"Notification service logs","detail":"The notification service itself successfully delivered every message it was asked to send"},{"id":"ev3","label":"Retry count metric","detail":"The outage-advisory job was retried roughly 40 times before someone manually stopped it"}],"question":"Which piece of evidence best explains how one retry produced forty duplicate copies of the same alert for some residents?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),
  ('mission-be17-07-o2-c1', 'mission-be17-07-o2', 1, 'multiple_choice', 'A job fails because the request body was malformed and will never parse correctly. Is retrying that job, unmodified, ever going to help?', '{"question":"A job fails because the request body was malformed and will never parse correctly no matter how many times it runs. Is retrying that job, unmodified, ever going to help?","options":[{"id":"a","text":"Yes -- retrying always eventually succeeds"},{"id":"b","text":"No -- this is a permanent, non-transient failure; retrying identical bad input produces the identical failure every time, and it should fail fast to a dead-letter path instead of consuming retry attempts"},{"id":"c","text":"Yes, as long as it retries at least 40 times"},{"id":"d","text":"Unknowable without seeing the queue''s priority setting"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be17-08-o1-c1', 'mission-be17-08-o1', 1, 'interactive_diagram', 'Put a well-behaved exponential-backoff retry sequence in order.', '{"diagramId":"exponential-backoff-sequence","hotspots":[{"id":"job_fails","label":"Job fails on first attempt","explanation":"The worker catches the failure instead of crashing the whole process."},{"id":"short_delay","label":"Wait a short base delay, then retry","explanation":"The first retry waits the smallest configured delay, e.g. 1 second."},{"id":"double_delay","label":"On the next failure, roughly double the delay","explanation":"Each subsequent failure doubles the wait -- 1s, then 2s, then 4s, and so on."},{"id":"cap_delay","label":"Cap the delay at a configured maximum","explanation":"Delays cannot grow forever -- a max delay keeps late retries from waiting absurdly long."},{"id":"give_up","label":"After a configured max attempt count, stop retrying","explanation":"Once attempts are exhausted, the job stops retrying and moves on to whatever failure path is configured next."}],"task":"Put a well-behaved exponential-backoff retry sequence in order."}'::jsonb, '{"correctOrderIds":["job_fails","short_delay","double_delay","cap_delay","give_up"]}'::jsonb),
  ('mission-be17-08-o2-c1', 'mission-be17-08-o2', 1, 'code_debugging', 'This retry config is meant to back off exponentially, but every retry actually waits the exact same delay. Which line is the bug?', '{"language":"typescript","code":"await alertQueue.add(\n  \"send-alert\",\n  { residentId, message },\n  {\n    attempts: 5,\n    backoff: {\n      type: \"fixed\",\n      delay: 2000\n    }\n  }\n);","question":"This retry config is meant to back off exponentially, but every retry actually waits the exact same delay. Which line is the bug?"}'::jsonb, '{"requiredLineIds":["      type: \"fixed\","]}'::jsonb),

  ('mission-be17-09-o1-c1', 'mission-be17-09-o1', 1, 'multiple_choice', 'A thousand alert jobs all fail at the exact same second because the notification service went down. All of them use identical exponential backoff, with no jitter. What happens next?', '{"question":"A thousand alert jobs all fail at the exact same second because the notification service went down. All of them use identical exponential backoff, with no jitter. What happens next?","options":[{"id":"a","text":"They retry at slightly different times, spread naturally over a few seconds"},{"id":"b","text":"They all compute the exact same delay and all retry at the exact same instant again, creating a synchronized retry storm against a service that may still be recovering"},{"id":"c","text":"Backoff without jitter has no downside at any scale"},{"id":"d","text":"Only the first job retries; the rest are cancelled automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be17-09-o2-c1', 'mission-be17-09-o2', 1, 'code_debugging', 'This function is supposed to add jitter to a backoff delay, but it always returns the exact same number for a given attempt. Which line is missing the actual randomness?', '{"language":"typescript","code":"function computeRetryDelay(attempt: number): number {\n  const base = 1000;\n  const maxDelay = 30000;\n  const exponential = Math.min(base * 2 ** attempt, maxDelay);\n  const jitteredDelay = exponential;\n  return jitteredDelay;\n}","question":"This function is supposed to add jitter to a backoff delay, but it always returns the exact same number for a given attempt. Which line is missing the actual randomness?"}'::jsonb, '{"requiredLineIds":["  const jitteredDelay = exponential;"]}'::jsonb),

  ('mission-be17-10-o1-c1', 'mission-be17-10-o1', 1, 'interactive_diagram', 'Put the lifecycle of a job that exhausts its retries in order.', '{"diagramId":"dead-letter-lifecycle","hotspots":[{"id":"job_fails_repeatedly","label":"Job fails on every attempt","explanation":"Each attempt fails, backing off further each time."},{"id":"attempts_exhausted","label":"Configured max attempts is reached","explanation":"The retry budget for this job is now used up."},{"id":"moved_to_dlq","label":"Job is moved to a dead-letter queue","explanation":"Instead of vanishing, the failed job and its failure history are written somewhere durable and separate."},{"id":"alert_raised","label":"A human-visible alert is raised on the dead-letter queue","explanation":"Someone is actually notified that a job needed manual attention, instead of the failure going unnoticed."},{"id":"manual_review","label":"A human reviews and resolves the dead-lettered job","explanation":"The job is inspected, fixed if possible, and either replayed or explicitly discarded -- a decision, not a disappearance."}],"task":"Put the lifecycle of a job that exhausts its retries in order."}'::jsonb, '{"correctOrderIds":["job_fails_repeatedly","attempts_exhausted","moved_to_dlq","alert_raised","manual_review"]}'::jsonb),
  ('mission-be17-10-o2-c1', 'mission-be17-10-o2', 1, 'investigation', 'Which piece of evidence best explains why failed outage-advisory jobs vanished with no record at all?', '{"evidence":[{"id":"ev1","label":"Queue config","detail":"The alert queue has attempts set, but no failed-job handler and no dead-letter queue configured anywhere"},{"id":"ev2","label":"Worker logs","detail":"Individual attempt failures were logged to stdout, which is not retained after the container restarts"},{"id":"ev3","label":"Monitoring dashboard","detail":"No alert exists for jobs reaching a failed state"}],"question":"Which single piece of evidence is the actual root cause, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be17-11-o1-c1', 'mission-be17-11-o1', 1, 'multiple_choice', 'What does it actually mean for a worker to be idempotent?', '{"question":"What does it actually mean for a worker to be idempotent?","options":[{"id":"a","text":"It processes jobs faster than a non-idempotent worker"},{"id":"b","text":"Running the same job twice (or more) produces the same end result as running it once -- a second run detects the work was already done and does not repeat the side effect"},{"id":"c","text":"It never fails"},{"id":"d","text":"It only accepts one job at a time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be17-11-o2-c1', 'mission-be17-11-o2', 1, 'code_debugging', 'This worker re-sends the alert on every attempt, including retries, with nothing to detect a message already sent. Which line is missing the idempotency check?', '{"language":"typescript","code":"alertWorker.process(async (job) => {\n  const { residentId, message, advisoryId } = job.data;\n  await notificationService.send(residentId, message);\n  return { sent: true };\n});","question":"This worker re-sends the alert on every attempt, including retries, with nothing to detect a message already sent. Which line needs an idempotency check added before it runs?"}'::jsonb, '{"requiredLineIds":["  await notificationService.send(residentId, message);"]}'::jsonb),

  ('mission-be17-12-o1-c1', 'mission-be17-12-o1', 1, 'multiple_choice', 'Explanation Alpha: "The notification service itself is unreliable and randomly drops messages -- that alone explains both the zero-alert and forty-alert residents." Does this account for the incident?', '{"question":"Explanation Alpha: \"The notification service itself is unreliable and randomly drops messages -- that alone explains both the zero-alert and forty-alert residents.\" Does this account for the incident?","options":[{"id":"a","text":"Yes -- an unreliable downstream service fully explains both extremes on its own"},{"id":"b","text":"No -- the notification service delivered everything it was actually asked to send; the real cause is upstream, in a retry loop with no idempotency key that resubmitted the entire batch from scratch on every failure, sending some residents the message dozens of times while a timeout mid-batch left others never reached at all"},{"id":"c","text":"Yes, but only for the zero-alert residents, not the forty-alert ones"},{"id":"d","text":"Unknowable without seeing the resident database schema"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be17-12-o2-c1', 'mission-be17-12-o2', 1, 'multiple_choice', 'Explanation Bravo: "Just add more workers so the batch finishes faster next time and nothing times out." Does adding more workers, by itself, fix what actually went wrong?', '{"question":"Explanation Bravo: \"Just add more workers so the batch finishes faster next time and nothing times out.\" Does adding more workers, by itself, fix what actually went wrong?","options":[{"id":"a","text":"Yes -- more throughput directly fixes duplicate and missing alerts"},{"id":"b","text":"No -- more workers might finish a batch faster, but it does nothing about a retry with no idempotency key duplicating sends, and nothing about failed jobs having no dead-letter path to land in; the same incident can still happen at a larger scale, just faster"},{"id":"c","text":"Yes, because more workers automatically add backoff and jitter"},{"id":"d","text":"Unknowable without seeing the server''s CPU usage"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be17-12-o3-c1', 'mission-be17-12-o3', 1, 'multiple_choice', 'Explanation Charlie: "Increase the request timeout so the original synchronous call has more time to finish the whole batch." Does that actually fix the incident?', '{"question":"Explanation Charlie: \"Increase the request timeout so the original synchronous call has more time to finish the whole batch.\" Does that actually fix the incident?","options":[{"id":"a","text":"Yes -- a longer timeout guarantees the batch completes"},{"id":"b","text":"No -- a longer timeout only delays the same failure at a larger scale; a million-resident batch running synchronously and inline inside one request is the root architectural mistake, and it needs to be a background job, not a request with more patience"},{"id":"c","text":"Yes, and it also fixes the missing dead-letter queue as a side effect"},{"id":"d","text":"Unknowable without seeing the resident count"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be17-12-o4-c1', 'mission-be17-12-o4', 1, 'boss_encounter', 'Having ruled out all three, state the full set of safeguards that would have prevented this incident.', '{"stages":[{"objectiveRef":"mission-be17-12-o1","label":"Explanation Alpha"},{"objectiveRef":"mission-be17-12-o2","label":"Explanation Bravo"},{"objectiveRef":"mission-be17-12-o3","label":"Explanation Charlie"}],"task":"Having ruled out all three, state the full set of safeguards that would have prevented this incident: move the send off the request path onto a real background job queue; retry failures with exponential backoff plus jitter instead of an immediate full resubmission; give every job an idempotency key so a retry detects work already done instead of repeating it; and wire up a dead-letter queue, with an actual alert on it, so jobs that exhaust their retries are surfaced to a human instead of disappearing."}'::jsonb, '{"requiredObjectiveIds":["mission-be17-12-o1","mission-be17-12-o2","mission-be17-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be17-01-o1-c1', 'orientation', 'Ask which of these has to happen before you can tell the caller anything meaningful at all, versus which could happen after you have already said "accepted."', 10, 1),
  ('mission-be17-01-o1-c1', 'concept', 'Validation and authorization decide whether the request is even legitimate -- the caller needs that answer before anything else proceeds.', 20, 2),
  ('mission-be17-01-o1-c1', 'solution', 'a -- validating and authorizing the request has to happen synchronously; sending to a million residents, generating a report, and reindexing are all slow work that belongs off the request path.', 30, 3),
  ('mission-be17-01-o2-c1', 'orientation', 'One entry here is a fixed limit, one is a per-call cost, and one is the code''s actual strategy -- only one of those is the root cause.', 10, 1),
  ('mission-be17-01-o2-c1', 'concept', 'Even a fast per-call cost, multiplied by a million calls awaited one after another inside a single request, adds up to far longer than any reasonable timeout.', 20, 2),
  ('mission-be17-01-o2-c1', 'solution', 'ev1 -- awaiting a million sequential sendAlert() calls inside one request handler is the actual design mistake; the timeout and per-call latency are just what exposed it.', 30, 3),

  ('mission-be17-02-o1-c1', 'orientation', 'Think about what happens to an in-memory array the instant the process holding it crashes or restarts.', 10, 1),
  ('mission-be17-02-o1-c1', 'solution', 'b -- durability across restarts and crashes is the whole point; an in-memory list disappears the moment the process does.', 20, 2),
  ('mission-be17-02-o2-c1', 'orientation', 'One of these is data, one is storage, one is a process, and one is a status -- match by role, not by name similarity.', 10, 1),
  ('mission-be17-02-o2-c1', 'solution', 'Job -> the unit of work. Queue -> the durable store. Worker -> the process that executes jobs. State -> the tracked lifecycle of each job.', 20, 2),

  ('mission-be17-03-o1-c1', 'orientation', 'Ask, for each line, whether it is adding work to the queue or taking work off it.', 10, 1),
  ('mission-be17-03-o1-c1', 'solution', 'Producer: accepts the request and enqueues, returns the response. Consumer: pulls jobs, does the real work, marks them done or failed.', 20, 2),
  ('mission-be17-03-o2-c1', 'orientation', 'Look for the evidence that describes the endpoint doing the actual sending itself, not handing it off.', 10, 1),
  ('mission-be17-03-o2-c1', 'solution', 'ev1 -- the handler sends every alert itself with no queue involved, meaning it is acting as producer and consumer at once, inline, inside the request.', 20, 2),

  ('mission-be17-04-o1-c1', 'orientation', 'Two of these are BullMQ objects your code creates directly. One is a method call. One is infrastructure BullMQ depends on but does not replace.', 10, 1),
  ('mission-be17-04-o1-c1', 'solution', 'Queue -> where producers add jobs. Worker -> what consumes and processes jobs. queue.add() -> the actual enqueue call. Redis -> the durable store BullMQ persists everything in.', 20, 2),
  ('mission-be17-04-o2-c1', 'orientation', 'This file only ever imports and uses one BullMQ class. Ask which class is responsible for actually running a processor function.', 10, 1),
  ('mission-be17-04-o2-c1', 'concept', 'A Queue only ever adds jobs. Nothing in this file ever creates a Worker, so nothing is ever listening to pull jobs off "outage-alerts" and run them.', 20, 2),
  ('mission-be17-04-o2-c1', 'solution', 'The Queue is declared and used to add jobs, but no Worker is ever created anywhere in this file to actually process them -- that missing Worker is the bug.', 30, 3),

  ('mission-be17-05-o1-c1', 'orientation', 'One of these runs once after waiting, one repeats on a fixed schedule forever, and one runs with no delay at all.', 10, 1),
  ('mission-be17-05-o1-c1', 'solution', 'i1 (one hour later, once) -> delayed. i2 (every night, forever) -> repeatable/scheduled. i3 (as soon as possible) -> immediate.', 20, 2),
  ('mission-be17-05-o2-c1', 'orientation', 'Read the cron pattern literally, field by field, instead of assuming it says what the job''s name implies.', 10, 1),
  ('mission-be17-05-o2-c1', 'concept', 'A cron pattern''s first field is minutes; "*/2 * * * *" means "every 2 minutes," not "at 2 AM."', 20, 2),
  ('mission-be17-05-o2-c1', 'solution', 'pattern: "*/2 * * * *" is a valid cron expression, but it means every 2 minutes, not nightly at 2 AM -- the intended pattern was likely "0 2 * * *".', 30, 3),

  ('mission-be17-06-o1-c1', 'orientation', 'Lower priority numbers usually mean more urgent, not less -- check that assumption against the order before you commit to it.', 10, 1),
  ('mission-be17-06-o1-c1', 'solution', 'emergency-alert (1), then password-reset-email (2), then weekly-digest (5), then analytics-rollup (10) -- lowest number processed first.', 20, 2),
  ('mission-be17-06-o2-c1', 'orientation', 'Ask what happens to a low-priority job if high-priority jobs never stop arriving.', 10, 1),
  ('mission-be17-06-o2-c1', 'solution', 'b -- strict priority with no adjustment risks starvation: a constant stream of higher-priority work can push a low-priority job back indefinitely.', 20, 2),

  ('mission-be17-07-o1-c1', 'orientation', 'Ask what information the retry logic would have needed to avoid re-sending to residents already messaged.', 10, 1),
  ('mission-be17-07-o1-c1', 'concept', 'A retry that resubmits the entire batch from the start, with no record of prior progress, treats every retry as if nothing happened before it.', 20, 2),
  ('mission-be17-07-o1-c1', 'solution', 'ev1 -- resubmitting the full batch from scratch on every failure, with no record of who was already messaged, is exactly how repeated failures became repeated duplicate sends.', 30, 3),
  ('mission-be17-07-o2-c1', 'orientation', 'Ask whether the input itself changes between attempts, or only the outcome you are hoping for changes.', 10, 1),
  ('mission-be17-07-o2-c1', 'solution', 'b -- a permanent failure caused by bad input will fail identically every time; retrying it is wasted attempts that delay the job reaching a dead-letter path where a human can actually fix the input.', 20, 2),

  ('mission-be17-08-o1-c1', 'orientation', 'Nothing can wait, double, or cap a delay before a failure has actually happened first.', 10, 1),
  ('mission-be17-08-o1-c1', 'concept', 'Exponential backoff has to eventually stop growing (a cap) and eventually stop retrying altogether (a max attempt count) -- unbounded growth or infinite retries are both their own failure modes.', 20, 2),
  ('mission-be17-08-o1-c1', 'solution', 'Job fails, wait a short base delay, retry; on failure the delay roughly doubles; the delay is capped at a max; after enough attempts, retrying stops.', 30, 3),
  ('mission-be17-08-o2-c1', 'orientation', 'BullMQ''s backoff option has a type field -- check what value actually means "grow the delay" versus "keep it constant."', 10, 1),
  ('mission-be17-08-o2-c1', 'concept', 'type: "fixed" always waits the same configured delay on every retry; only type: "exponential" actually doubles the delay each time.', 20, 2),
  ('mission-be17-08-o2-c1', 'solution', 'type: "fixed" is the bug -- it should be type: "exponential" for the delay to actually grow between retries instead of staying at a flat 2000ms.', 30, 3),

  ('mission-be17-09-o1-c1', 'orientation', 'Ask what "identical inputs producing identical outputs" means when a thousand jobs all failed at the same moment and all run the same backoff formula.', 10, 1),
  ('mission-be17-09-o1-c1', 'concept', 'A pure exponential-backoff formula with no randomness returns the exact same delay for every job at the same attempt number -- there is nothing to spread them apart in time.', 20, 2),
  ('mission-be17-09-o1-c1', 'solution', 'b -- with no jitter, every failed job computes an identical delay and all retry in lockstep, creating a synchronized retry storm against the same struggling service.', 30, 3),
  ('mission-be17-09-o2-c1', 'orientation', 'Search this function for anything that would make two calls with the same attempt number return different numbers. There is nothing.', 10, 1),
  ('mission-be17-09-o2-c1', 'concept', 'Jitter requires an actual source of randomness -- something like Math.random() folded into the delay -- not just a rename of the exponential value.', 20, 2),
  ('mission-be17-09-o2-c1', 'solution', 'const jitteredDelay = exponential; just copies the exponential value with no randomness added at all -- it needs something like exponential * (0.5 + Math.random() * 0.5) to actually jitter.', 30, 3),

  ('mission-be17-10-o1-c1', 'orientation', 'A job cannot be moved anywhere until its retry budget is actually used up.', 10, 1),
  ('mission-be17-10-o1-c1', 'concept', 'A dead-letter queue is only useful if a human is actually told something landed there -- storage without an alert just becomes a quieter place to lose track of failures.', 20, 2),
  ('mission-be17-10-o1-c1', 'solution', 'Repeated failure, attempts exhausted, moved to a dead-letter queue, an alert is raised on it, a human reviews and resolves it.', 30, 3),
  ('mission-be17-10-o2-c1', 'orientation', 'Two of these are symptoms of a failure being hard to see after the fact. One is the actual absence of a dead-letter path.', 10, 1),
  ('mission-be17-10-o2-c1', 'solution', 'ev1 -- there was never a failed-job handler or dead-letter queue configured at all, so exhausted jobs had nowhere to go and no record was kept.', 20, 2),

  ('mission-be17-11-o1-c1', 'orientation', 'Think about a light switch that is already on -- flipping "on" again does not turn it on twice.', 10, 1),
  ('mission-be17-11-o1-c1', 'solution', 'b -- idempotency means a repeat run recognizes the work is already done and does not repeat the side effect, so retries become safe instead of dangerous.', 20, 2),
  ('mission-be17-11-o2-c1', 'orientation', 'The job data includes an advisoryId alongside residentId -- ask what that field is for if nothing in the worker ever checks it.', 10, 1),
  ('mission-be17-11-o2-c1', 'concept', 'An idempotency check needs to look up, before sending, whether this exact (residentId, advisoryId) pair was already recorded as sent -- and skip the send if so.', 20, 2),
  ('mission-be17-11-o2-c1', 'solution', 'await notificationService.send(residentId, message); runs unconditionally on every attempt with no prior check against advisoryId + residentId, so every retry sends again from scratch.', 30, 3),

  ('mission-be17-12-o1-c1', 'orientation', 'Check what the notification service''s own logs actually say about what it was asked to do, versus what it actually delivered.', 10, 1),
  ('mission-be17-12-o1-c1', 'solution', 'b -- the notification service delivered everything it was asked to; the duplication and gaps trace to the retry logic upstream of it, not to the delivery layer itself.', 20, 2),
  ('mission-be17-12-o2-c1', 'orientation', 'Ask whether more capacity changes anything about what a retry actually does once it runs.', 10, 1),
  ('mission-be17-12-o2-c1', 'solution', 'b -- more workers change speed, not correctness; a resubmit-from-scratch retry with no dead-letter path duplicates and drops messages just as badly, only faster.', 20, 2),
  ('mission-be17-12-o3-c1', 'orientation', 'Ask what a longer timeout actually buys a batch that was never supposed to run synchronously in the first place.', 10, 1),
  ('mission-be17-12-o3-c1', 'solution', 'b -- a longer timeout just postpones the same architectural failure; the batch needs to be background work, not a request given more patience.', 20, 2),
  ('mission-be17-12-o4-c1', 'orientation', 'Every mission this Act taught you one piece of this answer -- count how many distinct safeguards were actually missing, not just one.', 15, 1),
  ('mission-be17-12-o4-c1', 'solution', 'Move the send to a background job queue instead of the request path; retry with exponential backoff plus jitter instead of an immediate full resubmission; give every job an idempotency key so retries detect already-completed work; and wire up an alerted dead-letter queue so exhausted jobs reach a human instead of disappearing.', 25, 2);
